// --- Design System Primitives (reused exact) ---
function Badge({children, tone, pulse}:{children:any, tone: BadgeTone, pulse?:boolean}){
  const map:any={
    READY:'bg-[#3FE0C8]/10 text-[#3FE0C8] border-[#3FE0C8]/20',
    RUNNING:'bg-[#5AA1FF]/10 text-[#5AA1FF] border-[#5AA1FF]/25',
    PAUSED:'bg-[#FFB84D]/10 text-[#FFB84D] border-[#FFB84D]/20',
    STOPPED:'bg-[#1A2128] text-[#8B96A3] border-[#252E38]',
    OFFLINE:'bg-[#1A2128]/90 text-[#6B7682] border-[#252E38]',
    ERROR:'bg-[#FF5A5A]/10 text-[#FF5A5A] border-[#FF5A5A]/20',
    FAILED:'bg-[#FF5A5A]/10 text-[#FF5A5A] border-[#FF5A5A]/20',
    DEMO:'bg-[#FFB84D]/10 text-[#FFB84D] border-[#FFB84D]/20',
    LAB:'bg-[#A78BFA]/10 text-[#A78BFA] border-[#A78BFA]/20',
    INFO:'bg-[#5AA1FF]/10 text-[#5AA1FF] border-[#5AA1FF]/20',
    WARN:'bg-[#FFB84D]/10 text-[#FFB84D] border-[#FFB84D]/20',
    OK:'bg-[#3FE0C8]/10 text-[#3FE0C8] border-[#3FE0C8]/20',
    AUTH:'bg-[#3FE0C8]/12 text-[#3FE0C8] border-[#3FE0C8]/25',
    UNKNOWN:'bg-[#1C232B] text-[#6B7682] border-[#252E38]',
    LOW:'bg-[#3FE0C8]/10 text-[#3FE0C8] border-[#3FE0C8]/20',
    MEDIUM:'bg-[#FFB84D]/10 text-[#FFB84D] border-[#FFB84D]/20',
    HIGH:'bg-[#FF7A45]/10 text-[#FF7A45] border-[#FF7A45]/20',
    CRITICAL:'bg-[#FF5A5A]/15 text-[#FF5A5A] border-[#FF5A5A]/30',
    QUEUED:'bg-[#1A2128] text-[#8B96A3] border-[#252E38]',
    COMPLETED:'bg-[#3FE0C8]/10 text-[#3FE0C8] border-[#3FE0C8]/20',
    CANCELLED:'bg-[#1C232B] text-[#6B7682] border-[#252E38]',
    NEW:'bg-[#FFB84D]/10 text-[#FFB84D] border-[#FFB84D]/20',
    ACK:'bg-[#5AA1FF]/10 text-[#5AA1FF] border-[#5AA1FF]/20',
    RESOLVED:'bg-[#3FE0C8]/10 text-[#3FE0C8] border-[#3FE0C8]/20',
    ASSOCIATED:'bg-[#3FE0C8]/10 text-[#3FE0C8] border-[#3FE0C8]/20',
    PROBING:'bg-[#5AA1FF]/10 text-[#5AA1FF] border-[#5AA1FF]/20',
    UNASSOC:'bg-[#1C232B] text-[#6B7682] border-[#252E38]',
  };
  return <span className={`inline-flex items-center gap-1 h-[18px] px-[6px] rounded-[4px] border text-[9px] font-bold tracking-[0.12em] mono ${map[tone]||map.OFFLINE}`}>{pulse && <span className="w-1 h-1 rounded-full bg-current animate-pulse"/>}{children}</span>;
}
function AgButton({children, variant='secondary', size='sm', icon:Icon, className='', ...props}:any){
  const v:any={
    primary:'bg-[#3FE0C8] text-black font-[700] hover:bg-[#5CEFD9] border border-[#3FE0C8]',
    secondary:'bg-[#16202A] text-[#C9D2DD] border border-[#222F3B] hover:bg-[#1B2833] hover:text-white',
    ghost:'bg-transparent text-[#7A8695] border border-transparent hover:bg-[#141A1F] hover:text-[#C9D2DD]',
    danger:'bg-[#2A1A1E] text-[#FF8A8A] border border-[#3A222A] hover:bg-[#3A222A]',
    lab:'bg-[#A78BFA] text-black font-[700] border border-[#A78BFA] hover:bg-[#B9A0FF]',
    blue:'bg-[#5A8CFF] text-white font-[600] border border-[#5A8CFF] hover:bg-[#6B99FF]',
  };
  const s:any={ xs:'h-[20px] px-2 text-[10px]', sm:'h-[24px] px-2.5 text-[11px]', md:'h-[28px] px-3.5 text-[11px]', lg:'h-[32px] px-4 text-[12px]' };
  return <button className={`inline-flex items-center justify-center gap-1.5 rounded-[5px] transition-all active:scale-[0.98] disabled:opacity-50 select-none ${v[variant]} ${s[size]} ${className}`} {...props}>{Icon && <Icon size={size==='xs'?10:12}/>}{children}</button>;
}
function AgTooltip({children, content, side='right'}:any){
  return (
    <div className="group/tooltip relative">
      {children}
      <div className={`pointer-events-none absolute z-[100] hidden group-hover/tooltip:flex items-center ${side==='right'?'left-[calc(100%+8px)] top-1/2 -translate-y-1/2':'bottom-[calc(100%+6px)] left-1/2 -translate-x-1/2'}`}>
        <div className="bg-[#141A1F] text-[#E6EAF0] border border-[#253240] rounded-[6px] shadow-[0_8px_32px_rgba(0,0,0,0.6)] px-2.5 py-1.5 text-[11px] font-medium whitespace-nowrap">{content}</div>
      </div>
    </div>
  );
}
function AirGuardMark({size=32}:{size?:number}){
  return (<div className="bg-[#151A1F] border border-[#222D38] grid place-items-center rounded-[7px]" style={{width:size,height:size}}><div className="relative"><div className="absolute -inset-2 bg-gradient-to-br from-[#3FE0C8]/15 to-[#5A8CFF]/15 blur-[6px] rounded-full" /><div className="relative w-[18px] h-[18px] flex items-center justify-center"><Shield size={18} className="text-[#3FE0C8] absolute" /><Wifi size={10} className="text-white absolute top-[6px]" /></div></div></div>);
}
